// ledger: non-royalty income/expense, plus artist-recoupment tracking, per the finance spec.
// `artist` is the artist's name (string, matches artists.name) or null for a general company entry.
export function ledgerRow(id, dateVal, type, category, description, amount, artist, recoupable, enteredBy, approvalStatus) {
  return { id, date: dateVal, type, category, description, amount, artist: artist || null, recoupable: !!recoupable, enteredBy, approvalStatus: approvalStatus || 'Approved', approvedBy: approvalStatus === 'Pending' ? '' : 'Maxwell', approvedAt: approvalStatus === 'Pending' ? '' : dateVal, createdAt: Date.parse(dateVal) || Date.now() };
}
